-- 90 Fireworks Night: the script only launches. A rocket is a particle
-- with a trail; where it dies its sub-emitters burst - a starburst sheet
-- played over its life, glitter twinkling through a four-frame star from a
-- frame of its own, smoke billowing over sixteen frames. The flashes on the
-- sky and the harbour are timed from the launch. Generated by
-- tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/90-fireworks-night.scene"
local NAMES = { "Gold", "Rose", "Teal" }
local FLIGHT = 1.25

local captions = true
local e = {}
local next_launch = 0.6
local t = 0
local pending = {}     -- { at, name }
local flash = { Gold = 0, Rose = 0, Teal = 0 }
local seed = 7

local function rand()
    seed = (seed * 1103515245 + 12345) % 2147483648
    return seed / 2147483648
end

local function launch(name)
    Particles.emit_burst(e["Launcher" .. name], 1)
    pending[#pending + 1] = { at = t + FLIGHT, name = name }
end

function init(entity)
    for _, n in ipairs(NAMES) do
        e["Launcher" .. n] = Entity.find_by_name("Launcher" .. n)
        e["Flash" .. n] = Entity.find_by_name("Flash" .. n)
        e["WaterFlash" .. n] = Entity.find_by_name("WaterFlash" .. n)
    end
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    t = t + dt
    if Input.is_key_just_pressed("Space") then
        for _, n in ipairs(NAMES) do launch(n) end
    end
    if t >= next_launch then
        launch(NAMES[math.floor(rand() * 3) + 1])
        if rand() < 0.3 then launch(NAMES[math.floor(rand() * 3) + 1]) end
        next_launch = t + 0.55 + rand() * 0.8
    end
    -- Each burst lights the sky and the water for a moment.
    local keep = {}
    for _, p in ipairs(pending) do
        if t >= p.at then flash[p.name] = 1 else keep[#keep + 1] = p end
    end
    pending = keep
    for _, n in ipairs(NAMES) do
        flash[n] = math.max(0, flash[n] - dt * 1.6)
        local r, g, b = Sprite.get_color(e["Flash" .. n])
        Sprite.set_color(e["Flash" .. n], r, g, b, 0.22 * flash[n])
        Sprite.set_color(e["WaterFlash" .. n], r, g, b, 0.35 * flash[n])
    end
end
